L.append(T(3012658,"Makaroni Keju Panggang","Menggunakan labu butternut untuk membuat saus yang lembut, adaptasi lezat dari hidangan favorit keluarga ini rendah garam, rendah kalium, rendah fosfat, dan rendah protein.","4",None,
["1 labu butternut (sekitar 600 g)","175 ml santan penuh lemak","2 sendok teh mustard Dijon","1 kubus kaldu sayuran rendah garam","1 sendok teh cuka sari apel","250 g pasta makaroni","Lada hitam","100 g remah roti","50 g keju cheddar","30 g kepingan almond","1 sendok makan peterseli segar (opsional)","200 g brokoli"],
["Panaskan oven terlebih dahulu hingga 160°C / 140°C fan / gas mark 3. Belah dua labu butternut dan buang bijinya. Letakkan dengan sisi daging menghadap ke bawah dalam loyang pemanggang dan tuang 200 ml air. Panggang dalam oven selama 1 jam 30 menit.","Biarkan labu agak dingin sebelum mengeruk dagingnya dengan sendok. Masukkan ke dalam blender bersama santan untuk membuat puree yang halus.","Setelah menjadi puree, panaskan perlahan dalam panci. Tambahkan mustard Dijon, cuka sari apel, dan hancurkan kubus kaldu ke dalamnya. Bumbui dengan lada dan tambahkan sedikit air ke dalam saus jika perlu. Didihkan perlahan selama 20 menit sampai mengental.","Didihkan air dalam panci besar. Masukkan makaroni dan masak selama 7 menit. Makaroni akan terus matang saat dipanggang. Tiriskan pasta dan campurkan dengan saus, lalu tuang ke dalam wadah tahan oven.","Parut keju dan campurkan dengan remah roti, almond, dan peterseli yang dicincang halus jika digunakan. Taburkan di atas pasta dan panggang dalam oven selama 10 menit sampai cokelat keemasan.","Didihkan air dalam panci dan masukkan brokoli. Masak sampai empuk, tiriskan, dan sajikan bersama pasta."],
[("Catatan Koki","Dengan sentuhan baru pada hidangan klasik, versi makaroni keju ini adalah hidangan yang menenangkan dan dapat dibekukan untuk dimasak dalam jumlah banyak."),("Karbohidrat","Pasta dan remah roti adalah sumber utama karbohidrat dalam hidangan ini dan nilainya diberikan bagi mereka yang telah dilatih dalam penyesuaian insulin."),("Kalium/fosfat","Dalam hidangan ini, labu butternut digunakan untuk saus yang memberikan sentuhan sehat dan menjaga resep tetap rendah kalium.\nHidangan ini rendah fosfat, meskipun tetap mengandung sedikit fosfat, dari keju. Jika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini."),("Protein","Hidangan ini rendah protein dan cocok jika Anda menjalani diet rendah protein."),("Bebas gluten","Gunakan pasta, remah roti, dan kaldu bebas gluten."),("Pilihan lebih sehat","Untuk menambah serat dalam hidangan ini, cobalah menggunakan pasta gandum utuh sebagai pengganti pasta makaroni."),("Pilihan lebih hemat","Ini adalah hidangan yang relatif murah. Untuk menghemat uang, Anda dapat membuat remah roti sendiri."),("Penyimpanan","Setelah dingin, simpan dalam wadah kedap udara dan taruh di lemari es. Gunakan dalam 3 hari dan panaskan kembali hingga benar-benar panas sebelum disajikan. Jika dibekukan, bagi menjadi porsi pada akhir langkah 4 dalam wadah kedap udara. Cairkan sepenuhnya, lalu tambahkan campuran topping dan lanjutkan memasak dari langkah 5."),("Tips","Untuk membuat remah roti segar, sobek roti menjadi potongan dan masukkan ke dalam food processor yang dipasangi pisau. Proses roti dalam beberapa kali putaran singkat sampai Anda mendapatkan remah roti dengan ukuran yang diinginkan.\nSebagai jalan pintas, Anda dapat membeli labu butternut segar potong dalam kemasan atau labu beku dan memasaknya sesuai petunjuk kemasan sebelum melanjutkan ke langkah 2.")],
[]))
L.append(T(3050711,"Fajita Ayam","Resep sehat ini mengandung kalori dalam jumlah sedang dan sumber protein yang baik.","4",None,
["200 g dada ayam, dipotong memanjang","1 paprika merah, dibuang bijinya dan diiris","1 paprika kuning, dibuang bijinya dan diiris","1 bawang bombai, dikupas dan diiris","1 sendok makan minyak zaitun","400 g kacang hitam kalengan, ditiriskan dan dibilas",("Bumbu fajita","1 sendok teh bubuk cabai pedas"),("Bumbu fajita","2 sendok teh paprika bubuk asap manis"),("Bumbu fajita","1 sendok teh jintan bubuk"),("Bumbu fajita","1 sendok teh bubuk bawang putih"),("Bumbu fajita","1 sendok teh oregano kering"),("Untuk penyajian","80 g krim asam"),("Untuk penyajian","160 g guacamole (atau Anda dapat membuatnya sendiri, lihat bagian tips)"),("Untuk penyajian","4 x tortilla tepung"),("Salad pendamping","200 g campuran daun salad"),("Salad pendamping","6-8 tomat ceri, dibelah dua"),("Salad pendamping","½ mentimun, dipotong dadu"),("Dressing","1 sendok makan minyak zaitun"),("Dressing","2 sendok teh cuka sari apel"),("Dressing","2 sendok teh mustard Dijon"),("Dressing","gilingan lada hitam")],
["Buat bumbu fajita dengan mencampur semua bahan. Tambahkan potongan ayam dan minyak zaitun lalu aduk sampai semuanya tercampur.","Panaskan air fryer terlebih dahulu hingga 190°C pada pengaturan roasting. Campurkan sayuran dan kacang dengan ayam lalu masak selama 15 menit, sambil mengocok keranjang dua kali selama memasak. Resep ini juga dapat dimasak dalam wajan di atas kompor jika diinginkan. Tumis ayam dalam minyak zaitun sampai kecokelatan di seluruh sisi, lalu tambahkan bahan lainnya dan masak dengan api sedang selama 15 menit.","Buat dressing salad dengan memasukkan semua bahan ke dalam mangkuk dan kocok bersama. Tambahkan dressing ini ke mentimun yang dipotong dadu, daun salad, dan tomat sesaat sebelum disajikan dan aduk rata.","Setelah campuran fajita ayam matang, sajikan dengan tortilla, krim asam, dan guacamole. Sajikan dengan salad yang sudah disiapkan di sampingnya."],
[("Catatan Koki","Resep cepat dan mudah ini sangat cocok untuk makan malam di tengah pekan."),("Panduan ukuran porsi untuk anak-anak","Ukuran penyajian didasarkan pada porsi dewasa. Berikut panduan untuk anak-anak:\nBalita (usia 1-4): ¼ porsi dewasa\nAnak kecil (usia 5-9): ½ porsi dewasa\nAnak yang lebih besar (usia 10-13): ¾ porsi dewasa\nRemaja (14+): 1 porsi dewasa\nBeberapa anak memang memiliki nafsu makan yang lebih besar daripada yang lain. Porsi anak Anda mungkin perlu disesuaikan dengan pola makan biasanya jika Anda merasa ukuran penyajian yang dianjurkan terlalu besar atau kecil. Kami menyarankan untuk berbicara dengan ahli gizi Anda sebelum menambah ukuran penyajian jika anak Anda kesulitan mengendalikan kalium atau fosfat."),("Karbohidrat","Tortilla adalah sumber utama karbohidrat dalam resep ini, dan nilainya diberikan bagi mereka yang telah dilatih dalam penyesuaian insulin."),("Kalium/fosfat","Meskipun menggunakan beberapa bahan tinggi kalium, seperti alpukat, resep ini rendah kalium jika mengikuti takaran dalam daftar bahan, cara memasak, dan ukuran penyajian. Karena itu, resep ini cocok bagi mereka yang dianjurkan menurunkan kalium dalam diet mereka. Resep ini juga rendah fosfat, namun tetap mengandung sedikit fosfat, terutama dari ayam, tortilla wrap, dan keju, sehingga jika Anda telah diresepkan pengikat fosfat, Anda harus meminumnya sesuai petunjuk.\nUntuk menurunkan fosfat lebih jauh, Anda dapat mempertimbangkan untuk mengganti sebagian atau seluruh daging dengan alternatif nabati, seperti 250 g kacang hitam kalengan-ditiriskan. Namun, hal ini juga akan mengurangi kandungan protein resep."),("Protein","Resep ini menyediakan sumber protein. Jika Anda dianjurkan untuk mengurangi protein, pertimbangkan untuk mengurangi ayam menjadi 100 g dan menambah kacang menjadi 200 g-250 g."),("Energi","Jika Anda perlu menaikkan berat badan, memiliki anak yang sedang tumbuh dan membutuhkan lebih banyak kalori, atau nafsu makan Anda kurang, Anda dapat menggunakan satu sendok makan minyak tambahan untuk memasak ayam. Menambahkan daging atau keju ekstra untuk meningkatkan kalori akan meningkatkan kandungan fosfat dalam resep."),("Vegetarian","Pertimbangkan untuk menggunakan 200 g tempe atau tahu sebagai pengganti ayam."),("Vegan","Pertimbangkan untuk menggunakan alternatif krim asam non-susu."),("Bebas gluten","Gunakan tortilla bebas gluten."),("Pilihan lebih sehat","Gunakan tortilla wrap gandum utuh."),("Pilihan lebih hemat","Gunakan minyak sayur/minyak bunga matahari.\nGunakan cuka yang Anda miliki di dapur.\nJika Anda tidak memiliki semua rempah, pertimbangkan untuk menggunakan campuran bumbu fajita (periksa versi tanpa tambahan garam).\nGunakan selada Iceberg sebagai pengganti campuran daun salad.\nGunakan mustard halus apa pun pilihan Anda."),("Penyimpanan","Hidangan ini paling enak dimakan saat baru dibuat. Sisa dressing dapat disimpan di lemari es hingga seminggu."),("Tips","Hidangan ini dapat disajikan dengan cangkang taco atau nasi sebagai alternatif."),("Tips: membuat guacamole sendiri","Anda dapat membuat guacamole sendiri:\n1 alpukat matang – dikupas, dibuang bijinya, dan dihaluskan dengan garpu\n1 cabai merah – dibuang bijinya dan dicincang halus\nair perasan 1 jeruk nipis\nsegenggam kecil ketumbar segar – dicincang halus\n1 bawang merah kecil – dikupas dan dicincang halus\ncampurkan semua bahan.")],
[]))
L.append(T(3067106,"Pasta Panggang Brokoli dan Kembang Kol","Untuk hidangan cepat, resep ini dapat disiapkan lebih awal pada hari yang sama dan dimasak dalam oven nanti (pastikan disimpan di lemari es selama itu).","2",None,
["150 g pasta kering – bentuk apa pun","200 g kuntum brokoli, segar atau beku","200 g kuntum kembang kol, segar atau beku","200 g krim keju","Lada hitam","1 sendok teh campuran rempah kering","15 g cheddar yang tajam, diparut","30 g remah roti"],
["Panaskan oven terlebih dahulu hingga 165°C. Didihkan air dalam panci dan masukkan pasta, masak selama 5 menit. Masukkan brokoli dan kembang kol ke dalam panci dan masak 8 menit lagi atau sampai semuanya matang, lalu tiriskan.","Campurkan lada hitam dan rempah kering ke dalam krim keju dalam mangkuk.","Tuang pasta dan sayuran ke dalam loyang pemanggang dan aduk bersama campuran krim keju. Taburi dengan remah roti dan keju cheddar. Masak selama 30 menit sampai cokelat keemasan.","Angkat dari oven dan diamkan selama 5 menit sebelum disajikan."],
[("Catatan Koki","Hidangan makan malam yang mewah dan lembut ini tinggi energi tetapi rendah garam, fosfat, dan kalium."),("Karbohidrat","Pasta adalah sumber utama karbohidrat dalam hidangan utama ini. Nilainya diberikan bagi mereka yang telah dilatih dalam penyesuaian insulin."),("Kalium/fosfat","Hidangan ini rendah kalium, karena takaran per orang telah diukur dengan cermat. Jika Anda dianjurkan menjalani diet rendah kalium, pastikan Anda mematuhi takaran yang tercantum. Resep ini rendah fosfat, namun tetap mengandung sedikit fosfat, sehingga jika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini."),("Protein","Protein berasal dari cheddar dan krim keju. Untuk mengurangi protein, Anda dapat menggunakan alternatif vegan yang sering kali lebih rendah protein dibandingkan sumber susu."),("Penyimpanan","Untuk hidangan cepat, resep ini dapat disiapkan lebih awal pada hari yang sama dan dimasak dalam oven nanti (pastikan disimpan di lemari es selama itu). Sisa makanan tahan di lemari es selama 2 hari.")],
[]))
L.append(T(3121590,"Chana Chaat","Ini adalah camilan tinggi protein dan rendah kalium yang cocok untuk penderita yang menjalani dialisis, tetapi sangat lezat sehingga semua orang pasti ingin mencicipinya.","3",None,
["1 tomat vine, besar","½ bawang merah","80 g mentimun","240 g buncis kacang arab (chickpea), kalengan dalam air","1 sendok teh chana chaat masala","3 sendok makan air perasan lemon",("Untuk penyajian","2 sendok makan yoghurt Yunani"),("Untuk penyajian","1 cabai hijau")],
["Untuk menyiapkan sayuran, cincang tomat, bawang merah, dan mentimun menjadi potongan kecil dengan ukuran yang mirip lalu letakkan dalam mangkuk. Cincang cabai dan sisihkan untuk nanti.","Tiriskan kacang arab dan masukkan ke campuran tomat, bawang merah, dan mentimun. Aduk.","Tambahkan air perasan lemon dan chana chaat masala. Aduk rata hingga tercampur.","Bagi campuran ke dalam tiga piring. Tambahkan yoghurt di atasnya dan taburkan cabai cincang sesuai selera."],
[("Catatan Koki","Chana chaat terasa asam segar dan mudah dibuat, tanpa perlu dimasak. Versi gurih ini ramah ginjal dan dirancang bagi mereka yang ingin menyantap sesuatu yang tradisional selama Ramadan."),("Karbohidrat","Yoghurt, kacang arab, tomat, dan mentimun semuanya merupakan sumber karbohidrat dalam hidangan ini. Nilai total karbohidrat diberikan bagi mereka yang telah dilatih dalam penyesuaian insulin."),("Kalium/fosfat","Sayuran mentah tinggi kalium, tetapi jika Anda mengikuti ukuran penyajian yang ditentukan, hidangan ini secara keseluruhan rendah kalium. Setiap porsi mengandung dua porsi buah dan sayuran, jadi harap berhati-hati jika Anda mengonsumsi lebih banyak sepanjang sisa hari.\nJika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini."),("Protein","Kacang arab adalah sumber protein yang baik, sehingga menjadikan ini camilan tinggi protein, yang ideal bagi mereka yang menjalani dialisis."),("Vegan","Gunakan yoghurt bebas susu."),("Pilihan lebih sehat","Untuk mengurangi kandungan lemak hidangan ini, Anda dapat menyajikannya dengan yoghurt rendah lemak atau tanpa yoghurt."),("Penyimpanan","Chana chaat dapat disimpan dalam wadah kedap udara dan disimpan di lemari es hingga dua hari.")],
[]))
